// vb_mkv_tbox_rom : engine-T T-box ROM, one table column v for two lanes (vb_mkv_eng_t, arch v4 section 14.2)
//   1024 x 32 dual-read-port ROM -> one RAMB36E1 (TDP, both ports read-only, DO_REG = 0); the output latches
//   do_a / do_b are the loop state of the round. Content is fixed (REQ-V4-3 ROM exception): precomputed
//   literal tables generated from spec/model/mkv_ref.py by tb/vb_mkv_tbox_rom/gen_tbox_rom.py (do not edit
//   by hand). Address = {half[1:0], byte[7:0]}, word byte x = bits [8x+7:8x] (contribution to target row x):
//     half 0  T_v    : M4[x][v] * S(a)                  half 2  Ti_v   : M4^-1[x][v] * S^-1(a)   (HALVES = 4)
//     half 1  XW_v   : x != v ? S(a)    : 0             half 3  XWi_v  : x != v ? S^-1(a) : 0    (HALVES = 4)
//   HALVES = 2 (DIR = "ENC"): halves 2 / 3 read 0. GF(2^8) poly 0x12B (ALG-GF-1).
module vb_mkv_tbox_rom #(
    parameter V      = 0,               //! table column v (0..3): lanes (y, v) of the transposed layout
    parameter HALVES = 4                //! 2: {T, XW} (ENC builds), 4: {T, XW, T^-1, XW^-1} (DEC / BOTH)
) (
    input  wire        clk,             //! clock
    input  wire        en,              //! read enable of both ports; 0 holds do_a / do_b
    input  wire [9:0]  addr_a,          //! port A address {half, byte}
    input  wire [9:0]  addr_b,          //! port B address {half, byte}
    output reg  [31:0] do_a,            //! port A data, registered (BRAM output latch)
    output reg  [31:0] do_b             //! port B data, registered (BRAM output latch)
);

